def find_maximal_frames(grid, h, w):
    """Find maximal rectangular frames for each color"""
    results = {}

    for color in range(9):
        for top in range(h):
            for left in range(w):
                # Try to extend right and down to find maximal frame
                right = left
                while right + 1 < w and grid[top][right + 1] == color:
                    right += 1

                if right == left:
                    continue  # Need at least width 2

                bottom = top
                while bottom + 1 < h and grid[bottom + 1][left] == color:
                    bottom += 1

                if bottom == top:
                    continue  # Need at least height 2

                # Valid minimal frame
                # Now check if it's a proper frame and try to expand
                is_proper = True

                # Check top boundary
                for c in range(left, right + 1):
                    if grid[top][c] != color:
                        is_proper = False
                        break

                if is_proper:
                    # Check bottom boundary
                    for c in range(left, right + 1):
                        if grid[bottom][c] != color:
                            is_proper = False
                            break

                if is_proper:
                    # Check left boundary
                    for r in range(top, bottom + 1):
                        if grid[r][left] != color:
                            is_proper = False
                            break

                if is_proper:
                    # Check right boundary
                    for r in range(top, bottom + 1):
                        if grid[r][right] != color:
