# Define a function to check if a region is a complete frame
def is_complete_frame(grid, top, left, bottom, right, color):
    """Check if the rectangular region is a complete frame:
    - All boundary cells are color
    - All  interior cells are NOT color
    """
    h = bottom - top + 1
    w = right - left + 1

    # Check boundary
    for r in range(top, bottom + 1):
        for c in range(left, right + 1):
            if r >= h or c >= w or grid[r][c] != color:
                return False

    # Check interior
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            if grid[r][c] == color:
                return False

    return True

