all_frames = set()

for color in range(9):
    for top in range(h):
        for left in range(len(lines_list[top].split())):
            if grid[top][left] != color:
                continue

            # Expand right
            right = left
            while right + 1 < len(grid[top]) and grid[top][right + 1] == color:
                right += 1

            if right == left:
