def check_frame_correct(top, bottom, left, right, color):
    """Check if this rectangle is a complete frame"""
    # Check boundary ONLY (top row, bottom row, left col, right col)
    is_boundary_valid = True
    for r in range(top, bottom + 1):
        if grid[r][left] != color:
            is_boundary_valid = False
        if grid[r][right] != color:
            is_boundary_valid = False

    for c in range(left, right + 1):
        if grid[top][c] != color:
            is_boundary_valid = False
        if grid[bottom][c] != color:
            is_boundary_valid = False

    if not is_boundary_valid:
        return False

    # Check interior (no cells should match color)
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            if grid[r][c] == color:
                return False

    return is_boundary_valid

